// DAOS Card -> Apple Wallet pass signer (Jake, Nov 19, 2026).
// GET ?token=<card_token> returns a signed .pkpass for that member's
// DAOS Card (QR encodes the card link, same as the in-app card).
// Secrets required: WALLET_PASS_CERT_PEM, WALLET_PASS_KEY_PEM,
// WALLET_WWDR_PEM, SUPABASE_SERVICE_ROLE_KEY (built-in), plus the
// built-in SUPABASE_URL.
import forge from "https://esm.sh/node-forge@1.3.1";

const ICONS: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": ""
};

function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
function strToBytes(s: string): Uint8Array {
  return new TextEncoder().encode(s);
}
async function sha1Hex(data: Uint8Array): Promise<string> {
  const h = await crypto.subtle.digest("SHA-1", data);
  return [...new Uint8Array(h)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
// Minimal stored (uncompressed) ZIP writer — a .pkpass is a zip.
const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c;
  }
  return t;
})();
function crc32(data: Uint8Array): number {
  let c = 0xffffffff;
  for (let i = 0; i < data.length; i++) c = CRC_TABLE[(c ^ data[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function zipStore(files: { name: string; data: Uint8Array }[]): Uint8Array {
  const chunks: Uint8Array[] = [];
  const central: Uint8Array[] = [];
  let offset = 0;
  const u16 = (v: number) => new Uint8Array([v & 255, (v >>> 8) & 255]);
  const u32 = (v: number) => new Uint8Array([v & 255, (v >>> 8) & 255, (v >>> 16) & 255, (v >>> 24) & 255]);
  const push = (arr: Uint8Array[], b: Uint8Array) => arr.push(b);
  for (const f of files) {
    const nameB = strToBytes(f.name);
    const crc = crc32(f.data);
    const local = [u32(0x04034b50), u16(20), u16(0x0800), u16(0), u16(0), u16(0x21), u32(crc), u32(f.data.length), u32(f.data.length), u16(nameB.length), u16(0)];
    for (const p of local) push(chunks, p);
    push(chunks, nameB);
    push(chunks, f.data);
    const cen = [u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(0), u16(0), u16(0x21), u32(crc), u32(f.data.length), u32(f.data.length), u16(nameB.length), u16(0), u16(0), u16(0), u16(0), u32(0), u32(offset)];
    for (const p of cen) push(central, p);
    push(central, nameB);
    offset += local.reduce((a, p) => a + p.length, 0) + nameB.length + f.data.length;
  }
  const cenSize = central.reduce((a, p) => a + p.length, 0);
  const end = [u32(0x06054b50), u16(0), u16(0), u16(files.length), u16(files.length), u32(cenSize), u32(offset), u16(0)];
  const all = [...chunks, ...central, ...end];
  const total = all.reduce((a, p) => a + p.length, 0);
  const out = new Uint8Array(total);
  let pos = 0;
  for (const p of all) { out.set(p, pos); pos += p.length; }
  return out;
}

Deno.serve(async (req) => {
  try {
    const url = new URL(req.url);
    const token = url.searchParams.get("token") || "";
    if (!token) return new Response("Missing token", { status: 400 });

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const profRes = await fetch(
      `${supabaseUrl}/rest/v1/profiles?card_token=eq.${encodeURIComponent(token)}&select=display_name,card_code,card_token`,
      { headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}` } },
    );
    const rows = await profRes.json();
    if (!Array.isArray(rows) || !rows.length) return new Response("Card not found", { status: 404 });
    const prof = rows[0];

    const cardUrl = `https://daosmedia.com/#/card/${prof.card_token}`;
    const passJson = {
      formatVersion: 1,
      passTypeIdentifier: "pass.com.daosmedia.card",
      serialNumber: prof.card_token,
      teamIdentifier: "Q948QC3RUA",
      organizationName: "The DAOS Foundation",
      description: "DAOS Card",
      logoText: "DAOS",
      foregroundColor: "rgb(255, 255, 255)",
      backgroundColor: "rgb(0, 0, 0)",
      labelColor: "rgb(225, 6, 0)",
      generic: {
        primaryFields: [{ key: "member", label: "MEMBER", value: prof.display_name || "DAOS member" }],
        secondaryFields: [{ key: "code", label: "CARD CODE", value: prof.card_code || "" }],
        auxiliaryFields: [{ key: "event", label: "NEXT EVENT", value: "DAOS Party - Dec 5, Harlem" }],
      },
      barcode: { format: "PKBarcodeFormatQR", message: cardUrl, messageEncoding: "iso-8859-1" },
      barcodes: [{ format: "PKBarcodeFormatQR", message: cardUrl, messageEncoding: "iso-8859-1" }],
    };

    const files: { name: string; data: Uint8Array }[] = [];
    files.push({ name: "pass.json", data: strToBytes(JSON.stringify(passJson, null, 2)) });
    for (const [name, b64] of Object.entries(ICONS)) files.push({ name, data: b64ToBytes(b64) });

    const manifest: Record<string, string> = {};
    for (const f of files) manifest[f.name] = await sha1Hex(f.data);
    const manifestBytes = strToBytes(JSON.stringify(manifest, null, 2));
    files.push({ name: "manifest.json", data: manifestBytes });

    const certPem = Deno.env.get("WALLET_PASS_CERT_PEM")!;
    const keyPem = Deno.env.get("WALLET_PASS_KEY_PEM")!;
    const wwdrPem = Deno.env.get("WALLET_WWDR_PEM")!;
    const cert = forge.pki.certificateFromPem(certPem);
    const wwdr = forge.pki.certificateFromPem(wwdrPem);
    const key = forge.pki.privateKeyFromPem(keyPem);
    const manifestStr = new TextDecoder().decode(manifestBytes);
    const p7 = forge.pkcs7.createSignedData();
    p7.content = forge.util.createBuffer(manifestStr);
    p7.addCertificate(cert);
    p7.addCertificate(wwdr);
    p7.addSigner({
      key,
      certificate: cert,
      digestAlgorithm: forge.pki.oids.sha256,
      authenticatedAttributes: [
        { type: forge.pki.oids.contentType, value: forge.pki.oids.data },
        { type: forge.pki.oids.signingTime, value: new Date() },
        { type: forge.pki.oids.messageDigest },
      ],
    });
    p7.sign({ detached: true });
    const der = forge.asn1.toDer(p7.toAsn1()).getBytes();
    const sigBytes = new Uint8Array(der.length);
    for (let i = 0; i < der.length; i++) sigBytes[i] = der.charCodeAt(i);
    files.push({ name: "signature", data: sigBytes });

    const pkpass = zipStore(files);
    return new Response(pkpass, {
      headers: {
        "Content-Type": "application/vnd.apple.pkpass",
        "Content-Disposition": 'attachment; filename="daos-card.pkpass"',
      },
    });
  } catch (e) {
    return new Response("Pass error: " + (e as Error).message, { status: 500 });
  }
});
